insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('f6996141-8b38-4faf-87b7-bb2e05e0dda6', 'b9554a3a-eec0-47c3-86a9-712432204ea9', $$inleiding: Amador daagt monopolist Badlands uit; doel marktaandeel 45%$$,
   $$economie-vwo-2022-i-sociaal-gamen-context1.png$$,
   $$Uitgeverij Amador gaat in januari 2020 de concurrentie aan met monopolist Badlands op de markt voor computerspellen. Amador biedt het nieuwe, gelijknamige, computerspel Amador aan. Amador is een computerspel waarin spelers samenwerken om gebieden te veroveren. Amador wordt aangeboden in de vorm van een persoonsgebonden abonnement: een speler betaalt een maandbedrag en heeft hierdoor het recht om het spel online te spelen. Badlands biedt het gelijknamige spel Badlands aan voor een abonnementsprijs van € 13 per maand. Uitgeverij Amador overweegt om een prijs vast te stellen van € 12 om een marktaandeel van de afzet te bereiken van minstens 45%. Marktonderzoek van marketinganalist Kim Klösters resulteert in de volgende vraagvergelijkingen van Amador en Badlands:$$, 'inline'),
  ('2e6e0060-5d24-4370-9063-8ca6f5032c97', 'b9554a3a-eec0-47c3-86a9-712432204ea9', $$vraagvergelijkingen van Amador en Badlands$$,
   $$economie-vwo-2022-i-sociaal-gamen-context2.png$$,
   $$qva = 400 – 30pa + 15pb
qvb = 600 + 20pa – 40pb
qva, qvb = de vraag in duizenden maandabonnementen Amador, respectievelijk Badlands
pa, pb = de abonnementsprijs in euro’s van Amador, respectievelijk Badlands$$, 'inline'),
  ('5b956d2b-2887-4252-8a62-0f1c4f0d95e6', 'b9554a3a-eec0-47c3-86a9-712432204ea9', $$Amador overweegt prijsverlaging van 10%; Badlands dreigt te reageren$$,
   $$economie-vwo-2022-i-sociaal-gamen-context3.png$$,
   $$Uitgeverij Amador overweegt (op basis van de cijfers van de analist) een agressievere aanpak door de introductieprijs met 10% te verlagen. Badlands dreigt te reageren met eenzelfde prijsverlaging. De analist brengt de gevolgen in kaart (figuur 1).$$, 'inline'),
  ('eafb17f2-29f6-4ab5-8652-bb7e63fb4e5e', 'b9554a3a-eec0-47c3-86a9-712432204ea9', $$figuur 1: spelboom met indexcijfers omzet van Amador en Badlands$$,
   $$economie-vwo-2022-i-sociaal-gamen-context4.png$$,
   $$Figuur 1 Indexcijfers omzet (afgerond) van Amador en Badlands
Amador behoudt prijs van € 12 → Badlands behoudt prijs van € 13: 100 ; 100
Amador behoudt prijs van € 12 → Badlands verlaagt prijs met 10%: 91,7 ; 104,6
Amador verlaagt prijs met 10% → Badlands behoudt prijs van € 13: x ; 92,5
Amador verlaagt prijs met 10% → Badlands verlaagt prijs met 10%: 96,3 ; 97,9
(eerste getal: Amador, tweede getal: Badlands)
Toelichting: een indexcijfer van 92,5 betekent een omzetdaling van 7,5% ten opzichte van de uitgangssituatie zonder prijsverlagingen.$$, 'inline'),
  ('64857fd3-f3a5-457c-b11b-a945ffcc1efa', 'b9554a3a-eec0-47c3-86a9-712432204ea9', $$analist: dreiging van Badlands is geloofwaardig$$,
   $$economie-vwo-2022-i-sociaal-gamen-context5.png$$,
   $$Volgens de analist is de uitgangssituatie (waarbij beide spelers geen prijsverlaging doorvoeren) niet realistisch en zij stelt op basis van figuur 1 het volgende: “De dreiging van Badlands is geloofwaardig, waardoor er een suboptimale situatie ontstaat en Amador dus hoe dan ook een lagere omzet kan verwachten dan in de uitgangssituatie.”$$, 'inline'),
  ('5c2c145b-a910-4147-b391-f81e5b529c6c', 'b9554a3a-eec0-47c3-86a9-712432204ea9', $$advies: prijsdiscriminatie naar aantal maanden spelen$$,
   $$economie-vwo-2022-i-sociaal-gamen-context6.png$$,
   $$De analist kijkt naar het toekomstig prijsbeleid van Amador en houdt Badlands verder buiten beschouwing. Zij adviseert een vorm van prijsdiscriminatie toe te passen: “Door het langdurig spelen verandert de betalingsbereidheid voor het spel, waardoor ook de vraaglijnen en prijselasticiteiten bij een prijs van € 12 veranderen. Ik adviseer daarom, op basis van tabel 1, om de startprijs met 10% te verlagen en na een jaar spelen deze verlaging voor het vervolgabonnement af te schaffen. Hierdoor zal de omzet van Amador toenemen”.$$, 'inline'),
  ('89dcaa25-4ee4-41f9-abf7-dbb97ac1a26f', 'b9554a3a-eec0-47c3-86a9-712432204ea9', $$tabel 1: prijselasticiteit bij € 12 naar maanden spelen$$,
   $$economie-vwo-2022-i-sociaal-gamen-context7.png$$,
   $$Tabel 1 Prijselasticiteit bij een prijs van € 12 naar maanden spelen
aantal maanden spelen | prijselasticiteit van de vraag bij € 12 op de verschillende vraaglijnen van Amador
0 | -1,53
2 | -1,32
6* | -1,18
12 | -1,00
24 | -0,92
36 | -0,89
* Voorbeeld: de groep spelers die 6 maanden het spel hebben gespeeld.$$, 'inline'),
  ('f0fd2ded-f41a-44cd-9f81-6608c0067c45', 'fcf27720-64a9-4434-8989-10e9ad7c023a', $$inleiding: Beau wil een eigen huis kopen met een hypotheek$$,
   $$economie-vwo-2022-i-een-eigen-huis-context1.png$$,
   $$Beau is een afgestudeerd psycholoog en huurt sinds 1 januari 2017 een kamer. Per 1 januari 2019 heeft ze een vast arbeidscontract en wil ze een eigen huis kopen. Ze kan een hypotheek krijgen van € 200.000 op basis van haar inkomen.$$, 'inline'),
  ('e97831ef-8e9b-4c89-8adc-5b0117263642', 'fcf27720-64a9-4434-8989-10e9ad7c023a', $$kredietverstrekking banken BNA en GNI op basis van H/A-verhouding$$,
   $$economie-vwo-2022-i-een-eigen-huis-context2.png$$,
   $$Beau oriënteert zich op de kredietverstrekking van de banken BNA en GNI. Tabellen 1 en 2 tonen de gevonden informatie. Daarin staan de hypotheekrentes, gebaseerd op de H/A-verhouding:$$, 'inline'),
  ('49763e91-5b7e-450d-976b-0e0d772eca4d', 'fcf27720-64a9-4434-8989-10e9ad7c023a', $$formule H/A-verhouding$$,
   $$economie-vwo-2022-i-een-eigen-huis-context3.png$$,
   $$H/A-verhouding = (het bedrag van de hypotheeklening / de aankoopsom van de woning) x 100%$$, 'inline'),
  ('60e66e91-a3a2-4aac-859f-62074917589c', 'fcf27720-64a9-4434-8989-10e9ad7c023a', $$tabel 1: rentepercentages bij rentevaste periode van 1 jaar$$,
   $$economie-vwo-2022-i-een-eigen-huis-context4.png$$,
   $$Tabel 1 Rentepercentages bij verschillende H/A-verhoudingen en een rentevaste periode van 1 jaar
bank | H/A-verhouding = 60% | H/A-verhouding = 80% | H/A-verhouding = 100%
BNA | 1,05% | 1,15% | 1,60%
GNI | 1,25% | 1,44% | 1,64%$$, 'inline'),
  ('624e6592-bade-4143-b384-a9ee195e437e', 'fcf27720-64a9-4434-8989-10e9ad7c023a', $$tabel 2: rentepercentages bij rentevaste periode van 10 jaar, met toelichting$$,
   $$economie-vwo-2022-i-een-eigen-huis-context5.png$$,
   $$Tabel 2 Rentepercentages bij verschillende H/A verhoudingen en een rentevaste periode van 10 jaar
bank | H/A-verhouding = 60% | H/A-verhouding = 80% | H/A-verhouding = 100%
BNA | 1,45% | 1,81% | 2,17%
GNI | 1,70% | 1,90% | 2,22%
Toelichting: een rentevaste periode is een periode waarin de rente niet wordt gewijzigd.$$, 'inline'),
  ('768fdacc-2a90-4d0c-a949-9c109d4fa07c', 'fcf27720-64a9-4434-8989-10e9ad7c023a', $$hypotheekrente stijgt met H/A-verhouding en rentevaste periode$$,
   $$economie-vwo-2022-i-een-eigen-huis-context6.png$$,
   $$Uit de tabellen blijkt dat de hypotheekrente stijgt naarmate de H/A-verhouding stijgt en naarmate de rentevaste periode langer is.$$, 'inline'),
  ('30cf5edc-d49b-4c7c-84c6-5dff70dc02e3', 'fcf27720-64a9-4434-8989-10e9ad7c023a', $$twee ontwikkelingen die de toekomstige hypotheekrente beïnvloeden$$,
   $$economie-vwo-2022-i-een-eigen-huis-context7.png$$,
   $$Beau twijfelt over de rentevaste periode die ze zal kiezen. In een economische analyse eind 2019 leest ze over twee economische ontwikkelingen die invloed hebben op de toekomstige hypotheekrente: i. de hoogconjunctuur in Nederland zal de komende jaren aanhouden. ii. pensioenfondsen en buitenlandse banken zullen vanaf volgend jaar ook hypotheken gaan aanbieden.$$, 'inline'),
  ('176242b8-ba8c-448e-8d7e-00656768e663', '91476f74-48f5-44d3-98ec-496cdf02e8f8', $$inleiding: handelsstromen van de VU met Cinai; gekoppelde valuta's$$,
   $$economie-vwo-2022-i-importheffing-context1.png$$,
   $$De overheid van de Verenigde Unie (VU) onderzoekt de positie van de VU ten opzichte van het buitenland en kijkt daarbij naar de internationale handelsstromen en in het bijzonder naar die met het land Cinai (zie tabel 1). De VU en Cinai hebben hun valuta’s aan elkaar gekoppeld.$$, 'inline'),
  ('0e00b80a-45da-45a1-aa30-6d32f53a2d6a', '91476f74-48f5-44d3-98ec-496cdf02e8f8', $$tabel 1: goederen- en dienstenstromen van de VU met het buitenland$$,
   $$economie-vwo-2022-i-importheffing-context2.png$$,
   $$Tabel 1 Goederen- en dienstenstromen van de VU met het buitenland in miljarden VU dollars (VU$)
variabele | 2000 | 2010 | 2020
exportwaarde van goederen en diensten (waarvan naar Cinai) | 900 (90) | 944 (91) | 1.013 (96)
importwaarde van goederen en diensten (waarvan uit Cinai) | 1.000 (250) | 1.125 (399) | 1.300 (519)
bbp VU | 3.000 | 3.300 | 4.550$$, 'inline'),
  ('a13d8bdd-d849-404a-8e39-9d7bd2f87004', '91476f74-48f5-44d3-98ec-496cdf02e8f8', $$twee stellingen van de overheid over concurrentiepositie en afhankelijkheid$$,
   $$economie-vwo-2022-i-importheffing-context3.png$$,
   $$Aan de hand van de tabel stelt de overheid van de VU het volgende: i. Onze internationale concurrentiepositie ten opzichte van Cinai is in de periode 2000–2020 verslechterd. ii. De eigen economie is in 2000–2020 afhankelijker geworden van Cinai.$$, 'inline'),
  ('eb85d81f-e1ae-44ca-b667-b25b111e2375', '91476f74-48f5-44d3-98ec-496cdf02e8f8', $$importheffing van VU$ 60 per batterij uit Cinai$$,
   $$economie-vwo-2022-i-importheffing-context4.png$$,
   $$Momenteel importeert de VU 90% van het binnenlandse vraagoverschot naar batterijen (in mobiele telefoons) uit Cinai. De overheid van de VU wil de eigen economie minder afhankelijk maken van Cinai en stelt een importheffing voor op batterijen uit Cinai van VU$ 60 per batterij in 2021. Om de gevolgen van de protectionistische maatregel te kunnen doorrekenen, maakt de overheid gebruik van een model (zie tabel 2). In het model wordt aangenomen dat andere landen hun productie van batterijen niet kunnen verhogen en de wereldmarktprijs onveranderd blijft.$$, 'inline'),
  ('9b0297a9-f8bb-43bf-a22a-6a4a2f0d1e35', '91476f74-48f5-44d3-98ec-496cdf02e8f8', $$tabel 2: binnenlandse markt van batterijen in de VU$$,
   $$economie-vwo-2022-i-importheffing-context5.png$$,
   $$Tabel 2 Binnenlandse markt van batterijen in de VU voor 2021.
Qv = –3P + 675 | collectieve binnenlandse vraag naar batterijen in miljoenen stuks
Qa = P – 125 | collectief aanbod van batterijen door binnenlandse producenten in miljoenen stuks
P | marktprijs per batterij op de binnenlandse markt in VU$
P wereldmarkt = 150 | wereldmarktprijs per batterij in VU$$$, 'inline'),
  ('51a0b7bc-a1bf-42c1-a55e-77e1eb930a7a', '91476f74-48f5-44d3-98ec-496cdf02e8f8', $$overheid verwacht geen import meer en beter saldo lopende rekening$$,
   $$economie-vwo-2022-i-importheffing-context6.png$$,
   $$De overheid van de VU verwacht door de invoering van de importheffing in 2021 dat de VU geen batterijen meer uit Cinai zal importeren en dat het saldo lopende rekening van de VU met Cinai zal verbeteren.$$, 'inline'),
  ('a509c1d4-edb2-47f2-af6b-a3d162369322', '91476f74-48f5-44d3-98ec-496cdf02e8f8', $$economen: directe investeringen omzeilen de heffing$$,
   $$economie-vwo-2022-i-importheffing-context7.png$$,
   $$In hun reactie geven enkele economen twee beweringen over het saldo lopende rekening van de VU: i. “Cinai kan de importheffing op lange termijn door directe investeringen in de VU volledig gaan omzeilen. ii. Deze directe investeringen leiden ertoe dat het saldo lopende rekening van de VU met Cinai enerzijds kan verslechteren, anderzijds kan verbeteren.”$$, 'inline'),
  ('15a6078e-5255-46a2-95e8-ba562c4c66c1', '91476f74-48f5-44d3-98ec-496cdf02e8f8', $$economen: protectionisme als sequentieel spel; financieringstekort$$,
   $$economie-vwo-2022-i-importheffing-context8.png$$,
   $$De overheid van de VU heeft een financieringstekort en gaat ervan uit dat door de importheffing het financieringstekort kan afnemen. De economen menen dat protectionistische maatregelen tussen landen kunnen worden opgevat als een sequentieel spel en dat het financieringstekort van de VU juist kan oplopen.$$, 'inline'),
  ('c9f77453-5b89-4fce-a5a8-2139a36ed0f2', '4973fe74-a71d-4799-8562-950d4354c41c', $$inleiding: dalende loonquote; definitie loonquote$$,
   $$economie-vwo-2022-i-loonquote-onder-de-loep-context1.png$$,
   $$Een steeds kleiner deel van de economische groei is de afgelopen jaren ten goede gekomen aan de productiefactor arbeid. Econoom Van Nassau onderzocht in 2018 mogelijke oorzaken van deze daling van de loonquote (het totale loon van alle werknemers in bedrijven als percentage van de totale netto toegevoegde waarde van bedrijven). Hij gebruikt figuur 1.$$, 'inline'),
  ('8761e8dd-c541-4e8b-b842-8655e4d05e8a', '4973fe74-a71d-4799-8562-950d4354c41c', $$figuur 1: factoren van invloed op de loonquote, met toelichting$$,
   $$economie-vwo-2022-i-loonquote-onder-de-loep-context2.png$$,
   $$Figuur 1 Factoren van invloed op de loonquote
globalisering → (+) technologische ontwikkeling; globalisering → (+) arbeidsproductiviteit; globalisering → (+) overig inkomen van bedrijven
technologische ontwikkeling → (+) arbeidsproductiviteit
arbeidsproductiviteit → (+) gemiddeld loon per arbeidsuur
gemiddeld loon per arbeidsuur → (+) technologische ontwikkeling; gemiddeld loon per arbeidsuur → (+) loonquote; gemiddeld loon per arbeidsuur → (-) overig inkomen van bedrijven
overig inkomen van bedrijven → (-) loonquote
Toelichting: globalisering houdt in dat er sprake is van een groeiende internationale handel en buitenlandse investeringen en een toegenomen betekenis van multinationals.$$, 'inline'),
  ('c31411fc-04c7-4b65-800f-9983993a6019', '4973fe74-a71d-4799-8562-950d4354c41c', $$verwachting: krapte op de arbeidsmarkt laat loonquote stijgen$$,
   $$economie-vwo-2022-i-loonquote-onder-de-loep-context3.png$$,
   $$Van Nassau verwacht echter dat krapte op de arbeidsmarkt tijdens de hoogconjunctuur in 2019 wel degelijk zal leiden tot een relatief sterkere ontwikkeling van de lonen, waardoor de loonquote in 2019 wel zal stijgen. Hij onderbouwt deze verwachting met gegevens uit tabel 1.$$, 'inline'),
  ('e7329b4c-9456-421a-9859-a4975729c9af', '4973fe74-a71d-4799-8562-950d4354c41c', $$tabel 1: macro-economische gegevens 2019 t.o.v. 2018$$,
   $$economie-vwo-2022-i-loonquote-onder-de-loep-context4.png$$,
   $$Tabel 1 macro-economische gegevens
| procentuele ontwikkeling 2019 t.o.v. 2018
productievolume in bedrijven | 2,7
inflatie | 2,5
gemiddeld loon per arbeidsuur in bedrijven | 4,0
werkgelegenheid in arbeidsuren in bedrijven | 1,5
arbeidsproductiviteit in bedrijven | 1,2$$, 'inline'),
  ('9167effe-917b-4b04-bd2a-7fee881fd0a4', '4973fe74-a71d-4799-8562-950d4354c41c', $$flexibele schil en de loongroei over de conjunctuur$$,
   $$economie-vwo-2022-i-loonquote-onder-de-loep-context5.png$$,
   $$Uit wetenschappelijk onderzoek blijkt dat werknemers met een flexibel contract gemiddeld een relatief laag loon hebben ten opzichte van werknemers met een vast contract. Op basis van dit onderzoek stelt econoom Van Houtven dat de ontwikkeling van de loonquote afhangt van de conjunctuur en de flexibele schil. De flexibele schil is het aantal flexibele contracten in verhouding tot het aantal vaste arbeidscontracten. Zij doet de volgende uitspraak: “De flexibele schil zorgt ervoor dat de loongroei minder afneemt in een laagconjunctuur en minder toeneemt in een hoogconjunctuur.” Dit is grafisch weergegeven in figuur 2.$$, 'inline'),
  ('942998f4-f956-473c-9d57-4b10f034b1fa', '4973fe74-a71d-4799-8562-950d4354c41c', $$figuur 2: effect flexibele schil op de loongroei, met toelichting$$,
   $$economie-vwo-2022-i-loonquote-onder-de-loep-context6.png$$,
   $$Figuur 2 Effect flexibele schil op de loongroei
Golvende lijnen van loongroei tegen de tijd; de stippellijn (met flexibele schil) schommelt minder sterk dan de doorgetrokken lijn (zonder flexibele schil).
Legenda: doorgetrokken lijn = procentuele loongroei zonder flexibele schil; stippellijn = procentuele loongroei met flexibele schil
Toelichting: De loongroei is de ontwikkeling van het gemiddeld loonniveau. In de figuur wordt verondersteld dat de loongroei gelijk opgaat met de conjunctuur$$, 'inline'),
  ('a1a4cf17-23ba-40c0-9cf5-7384c6db22b1', '4973fe74-a71d-4799-8562-950d4354c41c', $$Van Houtven: loonstarheid tijdens laagconjunctuur$$,
   $$economie-vwo-2022-i-loonquote-onder-de-loep-context7.png$$,
   $$Econoom Van Houtven meent bovendien dat tijdens een laagconjunctuur de verhouding tussen vraag en aanbod op de arbeidsmarkt verandert als gevolg van loonstarheid: hierdoor zullen de lonen ook minder hard stijgen als de conjunctuur weer aantrekt.$$, 'inline'),
  ('ae0ba5f5-846b-4983-bb8a-ff26af727dc9', 'ae3c7ee0-92e0-4f4e-b04d-3af473c41d20', $$inleiding: uitvaartverzekering van Funus met premie of afkoopsom$$,
   $$economie-vwo-2022-i-uitvaartverzekering-context1.png$$,
   $$Uitvaartonderneming Funus biedt een verzekering aan waarbij Funus de complete uitvaart verzorgt en betaalt. Klanten kunnen kiezen om maandelijks een premie te betalen of om eenmalig een bedrag te betalen (een afkoopsom). De hoogte van de premie of afkoopsom is mede afhankelijk van de leeftijd van de klant. Funus belegt de betaalde premies en afkoopsommen in aandelen en staatsobligaties. Funus adverteert met een kwalitatief goede verzorging van uitvaarten.$$, 'inline'),
  ('c02d327f-7a04-4251-a52a-fea396529ee3', 'ae3c7ee0-92e0-4f4e-b04d-3af473c41d20', $$Funus in financiële problemen; dekkingsgraad 85% onder minimum 130%$$,
   $$economie-vwo-2022-i-uitvaartverzekering-context2.png$$,
   $$In 2019 is Funus in financiële problemen gekomen. Oorzaken hiervan waren de aanhoudend lage rente en de sterker dan verwacht stijgende kosten van uitvaarten. Hierdoor heeft Funus te weinig vermogen om te voldoen aan zijn verplichtingen. De Nederlandsche Bank (DNB) is toezichthouder en maakt zich zorgen over de (toekomstige) dienstverlening door Funus, want de dekkingsgraad van Funus van 85% is lager dan de minimale eis van 130%.$$, 'inline'),
  ('244a352c-d1d7-4793-8cf1-3564fa0961dd', 'ae3c7ee0-92e0-4f4e-b04d-3af473c41d20', $$formule dekkingsgraad$$,
   $$economie-vwo-2022-i-uitvaartverzekering-context3.png$$,
   $$Dekkingsgraad = (huidig vermogen / contante waarde toekomstige verplichtingen) x 100%$$, 'inline'),
  ('7dae2fc1-bc59-4d2f-8cd5-186076def35c', 'ae3c7ee0-92e0-4f4e-b04d-3af473c41d20', $$toezicht wegens principaal-agentprobleem$$,
   $$economie-vwo-2022-i-uitvaartverzekering-context4.png$$,
   $$Een van de redenen om toezicht te houden op de bedrijfsvoering van uitvaartverzekeraars is het bestaan van een principaal-agentprobleem tussen verzekeraar en verzekerden.$$, 'inline'),
  ('99e09f13-80b2-4872-a65e-5504d9facd7d', 'ae3c7ee0-92e0-4f4e-b04d-3af473c41d20', $$mevrouw Sardjoe: afkoopsom € 6.000, uitvaart over 20 jaar € 7.500, rente 1,5%$$,
   $$economie-vwo-2022-i-uitvaartverzekering-context5.png$$,
   $$Mevrouw Sardjoe is 64 jaar en heeft besloten een uitvaartverzekering af te sluiten bij Funus. Ze kiest voor een afkoopsom van € 6.000. De gemiddelde levensverwachting is 84 jaar. Naar verwachting kost een uitvaart over 20 jaar gemiddeld € 7.500. Funus moet van DNB rekenen met een rente van 1,5% per jaar.$$, 'inline'),
  ('9407ef4e-bc40-42c5-97de-eba0bf2e610d', 'ae3c7ee0-92e0-4f4e-b04d-3af473c41d20', $$Funus: lage rente laat koersen van staatsobligaties stijgen$$,
   $$economie-vwo-2022-i-uitvaartverzekering-context6.png$$,
   $$Funus stelt dat de rente van 1,5% in eerste instantie leidt tot een lage dekkingsgraad, maar op den duur weer voor een stijgende dekkingsgraad: “Die rente is gebaseerd op de rente op staatsobligaties. Als gevolg van de aanhoudend lage rente zijn de koersen van staatsobligaties die wij al in bezit hebben, gestegen. Hierdoor kan de dekkingsgraad weer stijgen.”$$, 'inline'),
  ('2a96b9d6-0e1c-48b8-863e-c23e8a9d7e7e', 'ae3c7ee0-92e0-4f4e-b04d-3af473c41d20', $$DNB: vergrijzing en risicoaversie verschuiven de vraaglijn$$,
   $$economie-vwo-2022-i-uitvaartverzekering-context7.png$$,
   $$Uit onderzoek blijkt dat de dekkingsgraad verhoogd kan worden door een verhoging van de premie. De bevolking vergrijst en van ouderen is bekend dat zij meer risico-avers zijn dan jongeren. DNB stelt: “De vraaglijn van uitvaartverzekeringen zal daarom geleidelijk verschuiven, waardoor Funus, zelfs bij een hogere premie, een hogere omzet kan behalen en zo de dekkingsgraad verbetert.”$$, 'inline'),
  ('32b9ecfe-890d-43b7-ab34-2331cdec839b', 'ae3c7ee0-92e0-4f4e-b04d-3af473c41d20', $$overname van Funus door concurrent LADE$$,
   $$economie-vwo-2022-i-uitvaartverzekering-context8.png$$,
   $$Ondanks alle opties is het Funus niet gelukt om de financiële buffers te verhogen om zelfstandig te kunnen blijven. Concurrent LADE wil het totale polissenbestand en de beleggingen van Funus overnemen. LADE heeft ruim voldoende vermogen om, inclusief de verzekeringspolissen van Funus, te voldoen aan de vereiste dekkingsgraad. Ondanks de kosten van de overname, kan dit een positief effect hebben op de winstgevendheid van verzekeringspolissen van LADE na de overname.$$, 'inline'),
  ('3daafd66-dfb5-4abe-a0ca-a73923b45e3e', '214e78d7-0a25-4bd6-82c5-30a6fbedef8b', $$inleiding: Bike Mobility verhuurt leasefietsen met mobiliteitsgarantie$$,
   $$economie-vwo-2022-i-leasefiets-context1.png$$,
   $$Ellen en Daphne willen in een grote stad starten met de onderneming Bike Mobility. Klanten krijgen een fiets in bruikleen tegen betaling van een maandelijks abonnementsbedrag. De klanten hebben een mobiliteitsgarantie: bij schade kan de fiets worden omgeruild tegen een andere fiets bij een van de vele aangesloten fietsenmakers. Een app geeft aan waar er een fiets klaar staat. Bike Mobility zal de enige aanbieder van leasefietsen zijn in deze stad. Ellen en Daphne hebben een marktonderzoek gedaan (zie tabel 1).$$, 'inline'),
  ('159b2764-5998-4222-8332-fe89f70efaa2', '214e78d7-0a25-4bd6-82c5-30a6fbedef8b', $$tabel 1: resultaten marktonderzoek Bike Mobility, met toelichting$$,
   $$economie-vwo-2022-i-leasefiets-context2.png$$,
   $$Tabel 1 Resultaten marktonderzoek Bike Mobility
| aantal potentiële klanten in de groep | geschatte gemiddeld aantal reparaties per jaar bij fietsen in eigen bezit | geschatte gemiddeld aantal reparaties per jaar bij gebruik van leasefietsen | geschatte vraagvergelijking
groep 1 studenten | 80.000 | 2,5 | 4 | Qᵥ₁ = 60.000 – 1.500P
groep 2 overigen | 35.000 | 2 | 4 | Qᵥ₂ = 27.500 – 250P
Toelichting:
Qᵥ₁, Qᵥ₂ = de gevraagde hoeveelheid leasefietsen per maand van groep 1, respectievelijk 2
P = de prijs per maand in euro’s van een abonnement op een leasefiets.$$, 'inline'),
  ('36e4f5ed-24da-4ec2-9f3e-c39c8b10a723', '214e78d7-0a25-4bd6-82c5-30a6fbedef8b', $$collectieve vraagfunctie$$,
   $$economie-vwo-2022-i-leasefiets-context3.png$$,
   $$De collectieve vraagfunctie luidt:
Qᵥ = 87.500 – 1.750P (voor 17.500 < Qᵥ ≤ 87.500)$$, 'inline'),
  ('db81b75a-1542-4b76-af7e-ada6d873a627', '214e78d7-0a25-4bd6-82c5-30a6fbedef8b', $$overige gegevens van Bike Mobility: kosten en contractduur$$,
   $$economie-vwo-2022-i-leasefiets-context4.png$$,
   $$Overige gegevens van Bike Mobility:
− De reparatiekosten bedragen gemiddeld € 20 per reparatie. De klanten betalen Bike Mobility een eigen bijdrage van € 5 per reparatie.
− Per maand bedragen de overige variabele kosten € 10 per geleasete fiets.
− De vaste (constante) kosten bedragen € 150.000 per maand.
− Het leasecontract duurt minstens 6 maanden, daarna kunnen deelnemers de fiets op elk moment inleveren en hoeven zij vanaf dat moment niet meer te betalen.$$, 'inline'),
  ('6d8c8c64-c510-43cd-a637-ae222b3bac48', '214e78d7-0a25-4bd6-82c5-30a6fbedef8b', $$Daphne: maatregel tegen moral hazard is niet afdoende$$,
   $$economie-vwo-2022-i-leasefiets-context5.png$$,
   $$Daphne beweert dat uit de tabel en uit de overige gegevens blijkt dat Bike Mobility een maatregel heeft genomen tegen moral hazard, maar dat die maatregel niet helemaal afdoende is.$$, 'inline'),
  ('ba18381e-c1c7-4075-a4bd-ae634e80e938', '214e78d7-0a25-4bd6-82c5-30a6fbedef8b', $$discussie over toepassen van prijsdiscriminatie$$,
   $$economie-vwo-2022-i-leasefiets-context6.png$$,
   $$Ellen en Daphne discussiëren aan de hand van de gegevens of het toepassen van prijsdiscriminatie mogelijk is. Daarin stellen zij het volgende:
− Ellen zegt op basis van tabel 1 dat prijsdiscriminatie mogelijk is. Ze wijst op het verschil in maximale betalingsbereidheid van de twee groepen waardoor voor groep 2 een hogere prijs gerekend kan worden.
− Daphne zegt dat prijsdiscriminatie niet mogelijk is omdat aan één van de voorwaarden van prijsdiscriminatie niet is voldaan.$$, 'inline'),
  ('daa6f29b-9b52-466c-8315-6c0c29dc7baa', '214e78d7-0a25-4bd6-82c5-30a6fbedef8b', $$keuze voor maximale winst op basis van de collectieve vraag$$,
   $$economie-vwo-2022-i-leasefiets-context7.png$$,
   $$Ellen en Daphne zien af van prijsdiscriminatie en besluiten voor maximale winst te gaan op basis van de collectieve vraag.$$, 'inline'),
  ('f9b3590c-1ea4-4cd1-8f38-4e76d86f2e49', '214e78d7-0a25-4bd6-82c5-30a6fbedef8b', $$Ellen: lagere prijs voor groep 1 dan de winstmaximaliserende prijs$$,
   $$economie-vwo-2022-i-leasefiets-context8.png$$,
   $$Ellen en Daphne discussiëren verder over de prijs die ze willen hanteren voor groep 1. Ellen stelt voor om de prijs voor groep 1 lager vast te stellen dan de winstmaximaliserende prijs, om de kans te vergroten dat Bike Mobility ook op de lange termijn winst kan behouden.$$, 'inline'),
  ('2f97a315-ab80-4cd6-898e-5fe689b4162b', '214e78d7-0a25-4bd6-82c5-30a6fbedef8b', $$gemeenteraadslid: verwaarloosde fietsen en negatieve externe effecten$$,
   $$economie-vwo-2022-i-leasefiets-context9.png$$,
   $$Een gemeenteraadslid beweert: “Burgers in de gemeente klagen over het grote aantal verwaarloosde fietsen dat maanden in fietsenrekken staat zonder dat ze gebruikt worden. De gemeente moet daarom het initiatief van Bike Mobility steunen.” Het gemeenteraadslid stelt dat de manier waarop Bike Mobility werkt een prikkel inhoudt om negatieve externe effecten te verminderen en daarmee de maatschappelijke kosten verlaagt.$$, 'inline');

